Body:
I think it might be possible to resolve this with something like:
```import type { Plugin } from "@opencode-ai/plugin";

export const plugin: Plugin = async () => {
  let isAnthropicBedrock = false;

  return {
    "chat.params": async (input, _output) => {
      isAnthropicBedrock =
        input.model.providerID === "amazon-bedrock" &&
        input.model.api.id.includes("anthropic");
    },
    "experimental.chat.messages.transform": async (_input, output) => {
      if (!isAnthropicBedrock) return;
      for (const msg of output.messages) {
        msg.parts = msg.parts.filter((part) => part.type !== "reasoning");
      }
    },
  };
};
```

I solved it using this config

```json
{
  "$schema": "https://opencode.ai/config.json",
  "model": "azure-foundry/gpt-5.4-2",
  "theme": "opencode",
  "autoupdate": true,
  "provider": {
    "azure-foundry": {
      "type": "openai-compatible",
      "options": {
        "apiKey": "<api-key>",
        "baseURL": "https://myfoundry.services.ai.azure.com/api/projects/myfoundryproject/openai/v1"
      },
      "models": {
        "gpt-5.4-2": {
          "name": "gpt-5.4-2",
          "limit": { "context": 128000, "output": 16000 }
        }
      }
    }
  }
}
```

and a custom opencode plugin

```javascript
export const AzureFix = async () => {
  return {
    "chat.params": async (input, output) => {
      output.maxOutputTokens = undefined
    },
  }
}
```

